import json,hashlib,subprocess,sys
from pathlib import Path
repo=Path(__file__).resolve().parents[4];root=repo/'apps/1-4/say-and-name'
sys.path.insert(0,str(root/'tools'))
from prepare_silma import load
folder=Path(sys.argv[1]);report=json.loads((folder/'part-30.json').read_text());expected={r['path']:r for r in load()['items']}
levels=json.loads((root/'data/levels-inline-v8.js').read_text().split('=',1)[1].strip().rstrip(';'))
contexts={}
for rows in levels.values():
 for category,emoji,words in rows:
  for w in words.split('|'):contexts.setdefault(w,category)
items=[]
for row in report['items']:
 assert row['text']==expected[row['path']]['text']
 path=folder/Path(row['path']).relative_to('audio/silma')
 assert hashlib.sha256(path.read_bytes()).hexdigest()==row['sha256']
 subprocess.run(['ffmpeg','-v','error','-i',str(path),'-f','null','-'],check=True)
 if row['kind']=='word':items.append(dict(ar=row['key'],spoken=row['spoken'],category=contexts[row['key']],audio=row['path'],sha256=row['sha256']))
assert items
html='''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تجربة نطق SILMA — كلماتي مع أشيائي</title><style>*{box-sizing:border-box}body{margin:0;background:#edf7f4;color:#17343a;font-family:Tahoma,Arial,sans-serif}main{max-width:1000px;margin:auto;padding:16px}header{background:#087f78;color:white;padding:18px;border-radius:20px}h1{font-size:25px;margin:0 0 10px}p{line-height:1.8}aside{background:#fff5d5;border-radius:14px;padding:12px;margin:12px 0;line-height:1.8}article{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:center;background:white;border-radius:24px;padding:18px}button{font:inherit;border:0;border-radius:14px;padding:12px;min-height:48px;cursor:pointer;background:#087f78;color:white}button:focus-visible,input:focus-visible{outline:3px solid #e0a700}#picture{display:block;background:#f5fbf9;width:100%;padding:8px}#picture img{display:block;width:100%;height:310px;object-fit:contain;border-radius:18px}.copy{text-align:center}#name{font-size:46px;margin:16px 0}#category{color:#4b6a6a}#stage.listening{outline:4px solid #27b884}#listen{width:100%;font-size:22px}nav{display:flex;gap:10px;margin-top:14px}nav button{flex:1}.tools{display:flex;gap:12px;align-items:center;margin:12px 0;flex-wrap:wrap;background:white;padding:14px;border-radius:14px}input{width:22px;height:22px;vertical-align:middle}.cards{display:flex;overflow-x:auto;gap:10px;padding:10px 0;margin-top:12px}.card{flex:0 0 110px;background:white;color:#17343a;border:2px solid transparent;padding:8px}.card.current{border-color:#087f78}.card img{width:100%;height:85px;object-fit:contain;border-radius:10px}.card span{display:block;margin:8px 0}#status{min-height:28px;text-align:center}@media(max-width:600px){main{padding:10px}article{grid-template-columns:1fr;padding:12px}#picture img{height:240px}#name{font-size:38px}.card{flex-basis:92px}.card img{height:70px}}</style></head><body><main><header><h1>كلماتي مع أشيائي — اختبار صوت SILMA</h1><div>المس الصورة للاستماع إلى النطق العربي الجديد.</div></header><aside>هذه دفعة اختبار جزئية بصوت SILMA الفعلي، وليست الأصوات القديمة. لكل ملف نطق واحد، ويعيده التطبيق بعد وقفة عند تفعيل التكرار. سلامة النطق قيد المراجعة السمعية؛ أخبرنا بالكلمات التي تحتاج تصحيحًا.</aside><div class="tools"><label><input type="checkbox" id="repeat" checked> إعادة النطق بعد وقفة قصيرة</label><span id="count"></span></div><article id="stage"><button id="picture" aria-label="اسمع اسم الصورة"><img id="image" alt=""></button><div class="copy"><h2 id="name"></h2><p id="category"></p><button id="listen">🔊 اسمع الكلمة</button><nav><button id="prev">السابق</button><button id="next">التالي</button></nav><p id="position"></p></div></article><p id="status" role="status"></p><div id="cards" class="cards"></div></main><script src="data/word-images-map.js"></script><script src="data/word-images-context-map.js"></script><script>
'use strict';var words=ITEMS,index=0,audio=new Audio(),generation=0,pause=null,watch=null;
function picture(w){return 'assets/word-images/'+((window.APP360_WORD_IMAGE_CONTEXT_MAP||{})[w.category+'\\u0001'+w.ar]||(window.APP360_WORD_IMAGE_MAP||{})[w.ar])}
function stop(){generation++;clearTimeout(pause);clearTimeout(watch);audio.onended=null;audio.onerror=null;audio.pause();document.getElementById('stage').classList.remove('listening')}
function render(){stop();var w=words[index];document.getElementById('image').src=picture(w);document.getElementById('image').alt=w.ar;document.getElementById('name').textContent=w.spoken;document.getElementById('category').textContent=w.category;document.getElementById('position').textContent=(index+1)+' / '+words.length;document.getElementById('status').textContent='';document.querySelectorAll('.card').forEach(function(b,i){b.classList.toggle('current',i===index)})}
function speak(){stop();var token=generation,w=words[index],round=0;document.getElementById('status').textContent='';document.getElementById('stage').classList.add('listening');function fail(){if(token!==generation)return;stop();document.getElementById('status').textContent='تعذر تحميل تسجيل SILMA. اضغط زر الصوت للمحاولة مرة أخرى.'}function play(){if(token!==generation)return;audio.playbackRate=round?1.05:1;audio.preservesPitch=!round;audio.mozPreservesPitch=!round;audio.webkitPreservesPitch=!round;audio.src=w.audio;audio.onerror=fail;audio.onended=function(){if(token!==generation)return;clearTimeout(watch);if(round===0&&document.getElementById('repeat').checked){round++;document.getElementById('status').textContent='دورك: قل الكلمة';pause=setTimeout(function(){document.getElementById('status').textContent='';play()},1400)}else{document.getElementById('stage').classList.remove('listening')}};watch=setTimeout(fail,20000);audio.load();var p=audio.play();if(p&&p.catch)p.catch(fail)}play()}
words.forEach(function(w,i){var b=document.createElement('button');b.className='card';var img=document.createElement('img');img.src=picture(w);img.alt=w.ar;img.loading='lazy';var label=document.createElement('span');label.textContent=w.ar;b.appendChild(img);b.appendChild(label);b.onclick=function(){index=i;render();speak()};document.getElementById('cards').appendChild(b)});document.getElementById('count').textContent=words.length+' كلمة جاهزة';document.getElementById('picture').onclick=speak;document.getElementById('listen').onclick=speak;document.getElementById('repeat').onchange=stop;document.getElementById('prev').onclick=function(){index=(index-1+words.length)%words.length;render();speak()};document.getElementById('next').onclick=function(){index=(index+1)%words.length;render();speak()};document.addEventListener('visibilitychange',function(){if(document.hidden)stop()});render();
</script></body></html>'''.replace('ITEMS',json.dumps(items,ensure_ascii=False))
(root/'silma-listening-test.html').write_text(html)
(folder/'verified-items.json').write_text(json.dumps(items,ensure_ascii=False))
print('Verified actual SILMA files and prepared listening page:',len(items))
